"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left", so they have to describe the target process, not a snapshot of an
earlier call.

Three things decide whether the numbers are usable:

* every address and length is carried at the full pointer width, so a region
  above 4 GiB keeps its base and a reservation larger than 4 GiB keeps its
  length;
* reserved ranges are first class, because an exhausted address space is
  usually exhausted by reservations rather than by commits;
* a file name is only reported once it has been translated back into a path
  the reader can paste into a ticket and open.
"""

import ctypes

from . import _winapi as w
from .errors import WVasError

#: A mapped file name can be as long as an NT object name, which is well past
#: ``MAX_PATH``.  Sizing the buffer to the real limit keeps long paths intact.
PATH_BUFFER_CHARS = w.MAX_NT_PATH_CHARS

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}

_REGION_KEYS = ("base", "size", "state", "type", "protect", "path", "image")

#: NT namespace prefixes that a caller cannot hand to ``open()``.
_UNOPENABLE_PREFIXES = ("\\device\\", "\\??\\", "\\\\?\\", "\\\\.\\")


def protection_name(protect):
    """Map a ``PAGE_*`` protection value onto its short textual name.

    Pure: the modifier bits (``PAGE_GUARD``, ``PAGE_NOCACHE``,
    ``PAGE_WRITECOMBINE``) are masked off and the remaining base protection is
    looked up in a constant table.
    """
    try:
        protect = int(protect)
    except (TypeError, ValueError):
        return "?"
    return _PROTECTION_NAMES.get(protect & 0xFF, "?")


def type_name(region_type):
    """Map a ``MEM_*`` region type onto its short textual name. Pure."""
    try:
        region_type = int(region_type)
    except (TypeError, ValueError):
        return "private"
    return _TYPE_NAMES.get(region_type, "private")


# ---------------------------------------------------------------------------
# error handling
# ---------------------------------------------------------------------------

def _require_platform(pid=None):
    if not w.AVAILABLE:
        raise WVasError(
            "virtual address space auditing is only supported on Windows",
            kind="unsupported",
            pid=pid,
        )


def _check_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int) or pid <= 0:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    if pid > 0xFFFFFFFF:
        raise WVasError("pid is not a valid process id", kind="badarg", pid=pid)
    return pid


def _open_error(pid, code):
    """Classify a failed ``OpenProcess`` call."""
    if code in (w.ERROR_INVALID_PARAMETER, w.ERROR_FILE_NOT_FOUND):
        # Windows reports a pid that does not name a live process this way.
        return WVasError(
            "no such process", kind="no-such-process", pid=pid
        )
    if code == w.ERROR_ACCESS_DENIED:
        return WVasError(
            "the process cannot be opened for reading",
            kind="access-denied",
            pid=pid,
        )
    return WVasError(
        "OpenProcess failed with Win32 error %d" % (code,),
        kind="query-failed",
        pid=pid,
    )


def _open_process(pid):
    """Open ``pid`` for reading, mapping every failure onto a ``WVasError``."""
    _check_pid(pid)
    _require_platform(pid)

    ctypes.set_last_error(0)
    handle = w.OpenProcess(
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ, False, pid
    )
    if handle:
        return handle
    code = w.last_error()

    if code == w.ERROR_ACCESS_DENIED:
        # Distinguish "exists but is out of reach" from anything else by
        # asking for the weakest right that still proves the process exists.
        ctypes.set_last_error(0)
        probe = w.OpenProcess(
            w.PROCESS_QUERY_LIMITED_INFORMATION, False, pid
        )
        if probe:
            w.CloseHandle(probe)
        raise _open_error(pid, w.ERROR_ACCESS_DENIED)

    raise _open_error(pid, code)


# ---------------------------------------------------------------------------
# device path -> DOS path translation
# ---------------------------------------------------------------------------

_device_map = None


def _query_dos_device(name):
    buffer = ctypes.create_unicode_buffer(w.MAX_NT_PATH_CHARS)
    written = w.QueryDosDeviceW(name, buffer, w.MAX_NT_PATH_CHARS)
    if not written:
        return None
    # The call can return several NUL separated targets; the first one is the
    # current mapping.
    target = buffer[:written]
    target = target.split("\x00", 1)[0]
    return target or None


def _logical_drives():
    buffer = ctypes.create_unicode_buffer(1024)
    written = w.GetLogicalDriveStringsW(1024, buffer)
    if not written or written > 1024:
        # Fall back to probing the whole alphabet.
        return ["%s:" % chr(letter) for letter in range(ord("A"), ord("Z") + 1)]
    raw = buffer[:written]
    drives = []
    for entry in raw.split("\x00"):
        entry = entry.strip()
        if len(entry) >= 2 and entry[1] == ":":
            drives.append(entry[:2])
    return drives


def _build_device_map():
    """Map NT device names (``\\Device\\HarddiskVolume3``) onto drive letters."""
    mapping = []
    if not w.AVAILABLE:
        return mapping
    for drive in _logical_drives():
        target = _query_dos_device(drive)
        if target:
            mapping.append((target.rstrip("\\"), drive))
    # Longest device name first so that HarddiskVolume10 is not shadowed by
    # HarddiskVolume1.
    mapping.sort(key=lambda item: len(item[0]), reverse=True)
    return mapping


def _device_mapping(refresh=False):
    global _device_map
    if _device_map is None or refresh:
        _device_map = _build_device_map()
    return _device_map


def _strip_redirector_components(rest):
    """Drop the ``;Z:0000000000000000`` components a redirector path carries."""
    parts = rest.split("\\")
    while parts and (not parts[0] or parts[0].startswith(";")):
        parts.pop(0)
    return "\\".join(parts)


def _from_device_map(nt_path):
    lowered = nt_path.lower()
    for refresh in (False, True):
        for device, drive in _device_mapping(refresh=refresh):
            device_lower = device.lower()
            if not lowered.startswith(device_lower):
                continue
            remainder = nt_path[len(device):]
            if remainder and not remainder.startswith("\\"):
                continue  # a longer device name that merely shares a prefix
            return drive + (remainder or "\\")
        if _device_map:
            # The table was already complete; a second pass would not help
            # unless it was empty to begin with.
            if refresh:
                break
    return None


def _to_dos_path(nt_path):
    """Translate a native file name into a path the caller can open.

    Returns a drive letter path (``C:\\...``) or a UNC path
    (``\\\\server\\share\\...``), or ``None`` when the name cannot be turned
    into either.
    """
    if not nt_path:
        return None
    path = nt_path.replace("/", "\\")

    # Win32 extended-length and NT object manager prefixes.
    for prefix in ("\\\\?\\", "\\??\\"):
        if path.lower().startswith(prefix.lower()):
            rest = path[len(prefix):]
            if rest[:4].lower() == "unc\\":
                return _finalise("\\\\" + rest[4:])
            return _finalise(rest)

    if path.lower().startswith("\\device\\"):
        rest = path[len("\\device\\"):]
        head, _, tail = rest.partition("\\")
        head_lower = head.lower()
        if head_lower in ("mup", "lanmanredirector", "webdavredirector"):
            share = _strip_redirector_components(tail)
            if share.lower().startswith("lanmanredirector\\"):
                share = _strip_redirector_components(
                    share[len("lanmanredirector\\"):]
                )
            if not share:
                return None
            return _finalise("\\\\" + share)
        resolved = _from_device_map(path)
        if resolved:
            return _finalise(resolved)
        return None

    return _finalise(path)


def _finalise(path):
    """Accept only paths a caller can hand straight to the filesystem."""
    if not path:
        return None
    lowered = path.lower()
    for prefix in _UNOPENABLE_PREFIXES:
        if lowered.startswith(prefix):
            return None
    if len(path) >= 2 and path[1] == ":" and path[0].isalpha():
        return path
    if path.startswith("\\\\"):
        # A UNC path needs at least a server and a share to be openable.
        parts = [part for part in path[2:].split("\\") if part]
        if len(parts) >= 2:
            return path
        return None
    return None


# ---------------------------------------------------------------------------
# region walking
# ---------------------------------------------------------------------------

def _mapped_path(handle, base_address):
    """Return the DOS path of the file backing ``base_address``, or ``None``.

    ``GetMappedFileNameW`` answers with a native device path, and it fails for
    page-file backed (anonymous) sections.  Both cases become ``None``: an
    anonymous mapping has no file, so reporting an empty string for it would
    be indistinguishable from a resolved path of length zero.
    """
    buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    ctypes.set_last_error(0)
    written = w.GetMappedFileNameW(
        handle, ctypes.c_void_p(base_address), buffer, PATH_BUFFER_CHARS
    )
    if not written:
        return None
    return _to_dos_path(buffer[:written].split("\x00", 1)[0])


def _walk(handle, pid, include_reserved):
    """Yield one descriptor per committed (and optionally reserved) region."""
    result = []
    limit = w.max_application_address()
    mbi = w.MEMORY_BASIC_INFORMATION()
    size = ctypes.sizeof(mbi)
    address = 0
    queried_anything = False
    last_error = 0
    # Paths are resolved per allocation, not per region: a single image is
    # split into many regions that all share one backing file.
    path_cache = {}

    while address <= limit:
        ctypes.set_last_error(0)
        written = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(mbi), size
        )
        if written < size:
            last_error = w.last_error()
            break
        queried_anything = True

        base = mbi.BaseAddress or 0
        region_size = mbi.RegionSize or 0
        state = mbi.State

        if state in (w.MEM_COMMIT, w.MEM_RESERVE):
            if state == w.MEM_COMMIT or include_reserved:
                allocation_base = mbi.AllocationBase or 0
                if mbi.Type in (w.MEM_IMAGE, w.MEM_MAPPED):
                    key = allocation_base or base
                    if key not in path_cache:
                        path_cache[key] = _mapped_path(handle, base)
                    path = path_cache[key]
                else:
                    path = None
                result.append({
                    "base": base,
                    "size": region_size,
                    "state": "commit" if state == w.MEM_COMMIT else "reserve",
                    "type": type_name(mbi.Type),
                    "protect": protection_name(mbi.Protect),
                    "path": path,
                    "image": mbi.Type == w.MEM_IMAGE,
                })

        next_address = base + region_size
        if region_size == 0 or next_address <= address:
            next_address = address + 0x1000
        address = next_address

    if not queried_anything and not result:
        raise WVasError(
            "VirtualQueryEx failed with Win32 error %d" % (last_error,),
            kind="query-failed",
            pid=pid,
        )
    result.sort(key=lambda item: item["base"])
    return result


def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    The list is ascending by ``base``.  Committed regions are always present;
    reserved-but-uncommitted ranges are present when ``include_reserved`` is
    true.  Addresses and sizes are the values the system reports, at full
    pointer width.
    """
    handle = _open_process(pid)
    try:
        return _walk(handle, pid, bool(include_reserved))
    finally:
        w.CloseHandle(handle)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them.

    The result is the subset of :func:`regions` whose ``path`` is not ``None``,
    in the same order.
    """
    return [item for item in regions(pid) if item["path"] is not None]


# ---------------------------------------------------------------------------
# module listing
# ---------------------------------------------------------------------------

def _module_handles(handle):
    """Return the loader's module handles, 32 and 64 bit alike."""
    needed = w.DWORD(0)
    capacity = 256
    while True:
        array = (ctypes.c_void_p * capacity)()
        ctypes.set_last_error(0)
        ok = w.EnumProcessModulesEx(
            handle,
            ctypes.byref(array),
            ctypes.sizeof(array),
            ctypes.byref(needed),
            w.LIST_MODULES_ALL,
        )
        if not ok:
            return None
        pointer_size = ctypes.sizeof(ctypes.c_void_p)
        count = needed.value // pointer_size
        if count > capacity:
            capacity = count + 64
            continue
        return [array[index] or 0 for index in range(count)]


def _module_record(handle, module):
    buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    ctypes.set_last_error(0)
    written = w.GetModuleFileNameExW(
        handle, ctypes.c_void_p(module), buffer, PATH_BUFFER_CHARS
    )
    path = None
    if written:
        path = _to_dos_path(buffer[:written].split("\x00", 1)[0])

    info = w.MODULEINFO()
    size = 0
    if w.GetModuleInformation(
        handle, ctypes.c_void_p(module), ctypes.byref(info), ctypes.sizeof(info)
    ):
        size = int(info.SizeOfImage)
    return {"path": path, "base": module, "size": size}


def _images_from_regions(handle, pid):
    """Derive one record per mapped image by folding its regions together."""
    spans = {}
    for item in _walk(handle, pid, include_reserved=True):
        if not item["image"]:
            continue
        base = item["base"]
        end = base + item["size"]
        for allocation, span in spans.items():
            if allocation <= base <= span["end"]:
                span["end"] = max(span["end"], end)
                if span["path"] is None:
                    span["path"] = item["path"]
                break
        else:
            spans[base] = {"end": end, "path": item["path"]}
    return [
        {"path": span["path"], "base": base, "size": span["end"] - base}
        for base, span in spans.items()
    ]


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Every image appears exactly once and no file path is repeated.  An image
    whose file name cannot be translated into an openable path is still
    listed, with ``path`` set to ``None``.
    """
    handle = _open_process(pid)
    try:
        handles = _module_handles(handle)
        if handles is None:
            records = _images_from_regions(handle, pid)
        else:
            seen_bases = set()
            records = []
            for module in handles:
                if module in seen_bases:
                    continue
                seen_bases.add(module)
                records.append(_module_record(handle, module))
            for extra in _images_from_regions(handle, pid):
                if extra["base"] not in seen_bases:
                    seen_bases.add(extra["base"])
                    records.append(extra)
    finally:
        w.CloseHandle(handle)

    records.sort(key=lambda item: item["base"])

    unique = []
    seen_paths = set()
    for record in records:
        if record["path"] is not None:
            key = record["path"].lower()
            if key in seen_paths:
                continue
            seen_paths.add(key)
        unique.append(record)
    return unique

"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left", so they have to describe the target process, not a snapshot of an
earlier call.

Three properties decide whether the numbers are usable at all:

* every address and length is carried at the full pointer width, so a region
  above 4 GiB keeps its base and a reservation larger than 4 GiB keeps its
  length;
* reserved ranges are first class, because an address space is usually
  exhausted by reservations rather than by commits;
* a file name is only reported once it has been translated back into a path
  the reader can paste into a ticket and open.
"""

import ctypes

from . import _winapi as w
from .errors import WVasError

#: A mapped file name can be as long as an NT object name, which is well past
#: ``MAX_PATH``.  Sizing the buffer to the real limit keeps long paths intact.
PATH_BUFFER_CHARS = w.MAX_NT_PATH_CHARS

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}

#: Namespace prefixes that a caller cannot hand to the filesystem.
_UNOPENABLE_PREFIXES = ("\\device\\", "\\??\\", "\\\\?\\", "\\\\.\\")


def protection_name(protect):
    """Map a ``PAGE_*`` protection value onto its short textual name.

    Pure: the modifier bits (``PAGE_GUARD``, ``PAGE_NOCACHE``,
    ``PAGE_WRITECOMBINE``) are masked off and the remaining base protection is
    looked up in a constant table.  No process is consulted.
    """
    try:
        protect = int(protect)
    except (TypeError, ValueError):
        return "?"
    return _PROTECTION_NAMES.get(protect & 0xFF, "?")


def type_name(region_type):
    """Map a ``MEM_*`` region type onto its short textual name.

    Pure, like :func:`protection_name`.
    """
    try:
        region_type = int(region_type)
    except (TypeError, ValueError):
        return "private"
    return _TYPE_NAMES.get(region_type, "private")


# ---------------------------------------------------------------------------
# error classification
# ---------------------------------------------------------------------------

def _check_pid(pid):
    """Reject anything that cannot be a Windows process id."""
    if isinstance(pid, bool) or not isinstance(pid, int) or pid <= 0:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    if pid > 0xFFFFFFFF:
        raise WVasError("pid is not a valid process id", kind="badarg", pid=pid)
    return pid


def _require_platform(pid=None):
    if not w.AVAILABLE:
        raise WVasError(
            "virtual address space auditing is only supported on Windows",
            kind="unsupported",
            pid=pid,
        )


def _classify_open_failure(pid, code):
    """Turn a Win32 error from ``OpenProcess`` into a classified error."""
    if code in (w.ERROR_INVALID_PARAMETER, w.ERROR_FILE_NOT_FOUND):
        # This is how Windows answers for a pid that is not running.
        return WVasError("no such process", kind="no-such-process", pid=pid)
    if code == w.ERROR_ACCESS_DENIED:
        return WVasError(
            "the process exists but cannot be opened for reading",
            kind="access-denied",
            pid=pid,
        )
    return WVasError(
        "OpenProcess failed with Win32 error %d" % (code,),
        kind="query-failed",
        pid=pid,
    )


def _open_process(pid):
    """Open ``pid`` for reading; every failure becomes a :class:`WVasError`."""
    _check_pid(pid)
    _require_platform(pid)

    ctypes.set_last_error(0)
    handle = w.OpenProcess(
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ, False, pid
    )
    if handle:
        return handle
    raise _classify_open_failure(pid, w.last_error())


# ---------------------------------------------------------------------------
# native file name -> openable path
# ---------------------------------------------------------------------------

_device_map = None


def _query_dos_device(name):
    buffer = ctypes.create_unicode_buffer(w.MAX_NT_PATH_CHARS)
    written = w.QueryDosDeviceW(name, buffer, w.MAX_NT_PATH_CHARS)
    if not written:
        return None
    # The result can hold several NUL separated targets; the first one is the
    # mapping currently in force.
    target = buffer[:written].split("\x00", 1)[0]
    return target or None


def _logical_drives():
    buffer = ctypes.create_unicode_buffer(1024)
    written = w.GetLogicalDriveStringsW(1024, buffer)
    if written and written <= 1024:
        drives = []
        for entry in buffer[:written].split("\x00"):
            entry = entry.strip()
            if len(entry) >= 2 and entry[1] == ":":
                drives.append(entry[:2])
        if drives:
            return drives
    return ["%s:" % chr(letter) for letter in range(ord("A"), ord("Z") + 1)]


def _build_device_map():
    """Map NT device names onto drive letters, longest device name first."""
    mapping = []
    if not w.AVAILABLE:
        return mapping
    for drive in _logical_drives():
        target = _query_dos_device(drive)
        if target:
            mapping.append((target.rstrip("\\"), drive))
    # HarddiskVolume1 must not shadow HarddiskVolume10.
    mapping.sort(key=lambda item: len(item[0]), reverse=True)
    return mapping


def _lookup_device(path):
    """Replace a leading NT device name in ``path`` with its drive letter."""
    global _device_map
    for attempt in (0, 1):
        if _device_map is None or attempt:
            # A volume can be mounted after the table was built, so one
            # refresh is worth a try before giving up on the name.
            _device_map = _build_device_map()
        lowered = path.lower()
        for device, drive in _device_map:
            if not lowered.startswith(device.lower()):
                continue
            remainder = path[len(device):]
            if remainder and not remainder.startswith("\\"):
                continue  # only shares a prefix with this device name
            return drive + (remainder or "\\")
    return None


def _strip_redirector_prefix(rest):
    """Drop the ``;Z:0000000000000000`` components of a redirector path."""
    parts = rest.split("\\")
    while parts and (not parts[0] or parts[0].startswith(";")):
        parts.pop(0)
    return "\\".join(parts)


def _openable(path):
    """Return ``path`` if a caller can open it directly, else ``None``."""
    if not path:
        return None
    lowered = path.lower()
    for prefix in _UNOPENABLE_PREFIXES:
        if lowered.startswith(prefix):
            return None
    if len(path) >= 2 and path[0].isalpha() and path[1] == ":":
        return path
    if path.startswith("\\\\"):
        # A UNC path needs a server and a share before it names anything.
        parts = [part for part in path[2:].split("\\") if part]
        if len(parts) >= 2:
            return path
    return None


def _to_dos_path(native_path):
    """Translate a native file name into a path the caller can open.

    Accepts ``\\Device\\HarddiskVolumeN\\...``, ``\\??\\...``, ``\\\\?\\...``
    and names that are already in DOS form, and answers with a drive letter
    path or a UNC path.  Returns ``None`` when the name cannot be turned into
    either, because a path the reader cannot open is worse than no path.
    """
    if not native_path:
        return None
    path = native_path.replace("/", "\\")

    for prefix in ("\\\\?\\", "\\??\\"):
        if path.lower().startswith(prefix):
            rest = path[len(prefix):]
            if rest[:4].lower() == "unc\\":
                return _openable("\\\\" + rest[4:])
            return _openable(rest)

    if path.lower().startswith("\\device\\"):
        rest = path[len("\\device\\"):]
        head, _, tail = rest.partition("\\")
        if head.lower() in ("mup", "lanmanredirector", "webdavredirector"):
            share = _strip_redirector_prefix(tail)
            if share.lower().startswith("lanmanredirector\\"):
                share = _strip_redirector_prefix(
                    share[len("lanmanredirector\\"):]
                )
            return _openable("\\\\" + share) if share else None
        resolved = _lookup_device(path)
        return _openable(resolved) if resolved else None

    return _openable(path)


# ---------------------------------------------------------------------------
# region walking
# ---------------------------------------------------------------------------

def _mapped_path(handle, base_address):
    """Return the openable path of the file backing ``base_address``.

    ``GetMappedFileNameW`` answers with a native device path, and it fails
    outright for page-file backed (anonymous) sections.  Both cases collapse
    to ``None``: an anonymous mapping has no file behind it, so an empty
    string would claim a file whose name happens to be unknown.
    """
    buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    ctypes.set_last_error(0)
    written = w.GetMappedFileNameW(
        handle, ctypes.c_void_p(base_address), buffer, PATH_BUFFER_CHARS
    )
    if not written:
        return None
    return _to_dos_path(buffer[:written].split("\x00", 1)[0])


def _query_raw(handle, pid):
    """Walk the whole user mode address space of ``handle``.

    Yields ``(base, size, state, protect, type, allocation_base)`` for every
    range ``VirtualQueryEx`` describes, free ranges included.  All values are
    Python integers, so nothing is truncated to the width of a C ``long``.
    """
    limit = w.max_application_address()
    mbi = w.MEMORY_BASIC_INFORMATION()
    struct_size = ctypes.sizeof(mbi)
    address = 0
    answered = False
    failure = 0

    while address <= limit:
        ctypes.set_last_error(0)
        written = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(mbi), struct_size
        )
        if written < struct_size:
            failure = w.last_error()
            break
        answered = True

        base = mbi.BaseAddress or 0
        size = mbi.RegionSize or 0
        yield (base, size, mbi.State, mbi.Protect, mbi.Type,
               mbi.AllocationBase or 0)

        following = base + size
        if size == 0 or following <= address:
            # Never spin on a degenerate answer.
            following = address + 0x1000
        address = following

    if not answered:
        raise WVasError(
            "VirtualQueryEx failed with Win32 error %d" % (failure,),
            kind="query-failed",
            pid=pid,
        )


def _walk(handle, pid, include_reserved):
    """Build the region descriptors for ``handle``."""
    result = []
    # One image or mapping spans many regions that share a backing file, so
    # the (comparatively expensive) name query runs once per allocation.
    path_cache = {}

    for base, size, state, protect, mem_type, allocation in _query_raw(
        handle, pid
    ):
        if state == w.MEM_COMMIT:
            state_name = "commit"
        elif state == w.MEM_RESERVE:
            if not include_reserved:
                continue
            state_name = "reserve"
        else:
            continue  # MEM_FREE: not in use by the process

        if mem_type in (w.MEM_IMAGE, w.MEM_MAPPED):
            key = allocation or base
            if key not in path_cache:
                path_cache[key] = _mapped_path(handle, base)
            path = path_cache[key]
        else:
            path = None

        result.append({
            "base": base,
            "size": size,
            "state": state_name,
            "type": type_name(mem_type),
            "protect": protection_name(protect),
            "path": path,
            "image": mem_type == w.MEM_IMAGE,
        })

    result.sort(key=lambda item: item["base"])
    return result


def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    The list is ascending by ``base``.  Committed regions are always present;
    reserved-but-uncommitted ranges are present as well when
    ``include_reserved`` is true.  ``base`` and ``size`` are exactly what
    ``VirtualQueryEx`` reports, at full pointer width.
    """
    handle = _open_process(pid)
    try:
        return _walk(handle, pid, bool(include_reserved))
    finally:
        w.CloseHandle(handle)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them.

    The subset of :func:`regions` whose ``path`` is not ``None``, in the same
    order.
    """
    return [item for item in regions(pid) if item["path"] is not None]


# ---------------------------------------------------------------------------
# module listing
# ---------------------------------------------------------------------------

def _module_handles(handle):
    """Return the loader's module handles, or ``None`` if it cannot be read.

    ``LIST_MODULES_ALL`` covers 32 and 64 bit targets alike, and the buffer is
    grown until the loader's whole list fits, so no module is dropped.
    """
    needed = w.DWORD(0)
    capacity = 256
    pointer_size = ctypes.sizeof(ctypes.c_void_p)
    for _ in range(8):
        array = (ctypes.c_void_p * capacity)()
        ctypes.set_last_error(0)
        ok = w.EnumProcessModulesEx(
            handle,
            ctypes.byref(array),
            ctypes.sizeof(array),
            ctypes.byref(needed),
            w.LIST_MODULES_ALL,
        )
        if not ok:
            return None
        count = needed.value // pointer_size
        if count > capacity:
            capacity = count + 64
            continue
        return [array[index] or 0 for index in range(count)]
    return None


def _module_record(handle, module):
    """Describe one loaded image: its path, base address and image size."""
    buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    ctypes.set_last_error(0)
    written = w.GetModuleFileNameExW(
        handle, ctypes.c_void_p(module), buffer, PATH_BUFFER_CHARS
    )
    path = None
    if written:
        path = _to_dos_path(buffer[:written].split("\x00", 1)[0])
    if path is None:
        # The loader name was unusable; the section name is a second chance.
        path = _mapped_path(handle, module)

    size = 0
    info = w.MODULEINFO()
    if w.GetModuleInformation(
        handle, ctypes.c_void_p(module), ctypes.byref(info), ctypes.sizeof(info)
    ):
        size = int(info.SizeOfImage)
    if not size:
        size = _image_span(handle, module)
    return {"path": path, "base": module, "size": size}


def _image_span(handle, base):
    """Measure a mapped image by folding the regions of its allocation."""
    mbi = w.MEMORY_BASIC_INFORMATION()
    struct_size = ctypes.sizeof(mbi)
    address = base
    end = base
    while True:
        ctypes.set_last_error(0)
        if w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(mbi), struct_size
        ) < struct_size:
            break
        if (mbi.AllocationBase or 0) != base or mbi.State == w.MEM_FREE:
            break
        size = mbi.RegionSize or 0
        end = (mbi.BaseAddress or 0) + size
        if size == 0 or end <= address:
            break
        address = end
    return end - base


def _images_from_regions(handle, pid):
    """Derive the loaded images from the image mappings in the address space.

    Used when the loader's module list is out of reach, so that an audit still
    reports which images are mapped and where.
    """
    spans = {}
    for base, size, state, _protect, mem_type, allocation in _query_raw(
        handle, pid
    ):
        if mem_type != w.MEM_IMAGE:
            continue
        if state not in (w.MEM_COMMIT, w.MEM_RESERVE):
            continue
        key = allocation or base
        span = spans.get(key)
        if span is None:
            spans[key] = {"end": base + size, "path": None}
        else:
            span["end"] = max(span["end"], base + size)
    records = []
    for key, span in spans.items():
        records.append({
            "path": _mapped_path(handle, key),
            "base": key,
            "size": span["end"] - key,
        })
    return records


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Every image appears exactly once and no file path is repeated.  An image
    whose file name cannot be translated into a path the caller can open is
    still listed, with ``path`` set to ``None``, so the list stays complete.
    """
    handle = _open_process(pid)
    try:
        handles = _module_handles(handle)
        if handles is None:
            records = _images_from_regions(handle, pid)
        else:
            records = []
            seen_bases = set()
            for module in handles:
                if module in seen_bases:
                    continue
                seen_bases.add(module)
                records.append(_module_record(handle, module))
    finally:
        w.CloseHandle(handle)

    records.sort(key=lambda item: item["base"])

    unique = []
    seen_paths = set()
    for record in records:
        if record["path"] is not None:
            key = record["path"].lower()
            if key in seen_paths:
                continue
            seen_paths.add(key)
        unique.append(record)
    return unique

